{
 "content": "def transform(grid):
    # Identify 3x3 glyphs: T, plus-like? classify by glyph positions. Output 3x6 categorical presence.
    h, w = len(grid), len(grid[0])
    comps=[]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==2 and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); pts=[]
                while stack:
                    x,y=stack.pop(); pts.append((x,y))
                    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
                comps.append(pts)
    # Each object is 4 pixels, local footprint encodes T orientation. Output marks objects in two groups across 3 rows.
    out=[[0]*6 for _ in range(3)]
    for pts in comps:
        r0=min(r for r,c in pts); c0=min(c for r,c in pts)
        shape={(r-r0,c-c0) for r,c in pts}
        # divide into left/right by spatial half, and top/bottom by vertical half.
        side=0 if c0 < w/2 else 1
        row=0 if r0 < h/3 else (2 if r0 >= 2*h/3 else 1)
        # Shapes with top bar get 3; bottom bar get 1.
        val=3 if (0,0) in shape and (0,1) in shape and (0,2) in shape else 1
        out[row][side*3+(0 if val==3 else 2)] = val
    return out
"
