    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen: continue
            q=[(r,c)];seen.add((r,c));p=[]
            while q:
                x,y=q.pop();p.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
            comps.append(p)
    out=[[0]*6 for _ in range(3)]
    for p in comps:
        r0=min(x for x,y in p);c0=min(y for x,y in p);shape={(x-r0,y-c0) for x,y in p}
        val=3 if all((0,j) in shape for j in range(3)) else 1
        # vertical location has three bands, horizontal location is one of two columns per value
        row=0 if r0 < h/3 else 2
        col=(0 if c0 < w/2 else 3) + (0 if val==3 else 2)
        out[row][col]=val
    return out
"
