{
 "content": "def transform(grid):
    # Components are 4-cell T glyphs. Output records glyph orientations by their
    # order in the input's four quadrants: each quadrant maps to one output slot.
    h,w=len(grid),len(grid[0]);seen=set();objects=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=2 or (r,c) in seen: continue
       q=[(r,c)];seen.add((r,c));pts=[]
       while q:
        x,y=q.pop();pts.append((x,y))
        for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
         if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
       objects.append(pts)
    out=[[0]*6 for _ in range(3)]
    # Four output sites determined by ordering glyph centers, relative to canvas.
    for pts in objects:
      r0=min(x for x,y in pts);c0=min(y for x,y in pts)
      sh={(x-r0,y-c0) for x,y in pts}
      v=3 if all((0,j) in sh for j in range(3)) else 1
      rr=0 if r0 < h/2 else 2
      cc=0 if c0 < w/2 else 3
      out[rr][cc]=v
    return out
"
}

