    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); pts=[]
            while q:
                x,y=q.pop(); pts.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            comps.append(pts)
    out=[[0]*6 for _ in range(3)]
    for pts in comps:
        r0=min(r for r,c in pts); c0=min(c for r,c in pts)
        shape={(r-r0,c-c0) for r,c in pts}
        v=3 if all((0,j) in shape for j in range(3)) else 1
        # Map horizontal position into left/right output panels and vertical position into top/bottom rows.
        row=0 if r0 < 0.6*h else 2
        col=0 if c0 < w/2 else 3
        # Keep T orientation in its panel's left or right marker location.
        col += 0 if v==3 else 2
        out[row][col]=v
    return out
